<?php require 'admin_bootstrap.php'; $title='Student Management'; $students=$pdo->query("SELECT * FROM users WHERE role='student' ORDER BY name")->fetchAll(); require 'header.php'; admin_flash_html(); ?>
<section class="section"><div class="card-head"><div><span class="eyebrow">STUDENT MANAGEMENT</span><h2>Student Accounts</h2></div><input id="student-search" placeholder="Search student..." style="max-width:260px"></div>
<div class="table-scroll"><table class="table" id="student-table"><tr><th>Student</th><th>ID</th><th>Program</th><th>Email</th><th>Status</th><th>Action</th></tr>
<?php foreach($students as $s): $ast=$s['account_status']??'Active'; ?><tr data-student-search="<?=e(strtolower($s['name'].' '.$s['student_id'].' '.$s['program'].' '.$s['email']))?>"><td><b><?=e($s['name'])?></b></td><td><?=e($s['student_id']?:'—')?></td><td><?=e($s['program']?:'—')?></td><td><?=e($s['email'])?></td><td><span class="badge <?=strtolower($ast)==='active'?'approved':'rejected'?>"><?=e($ast)?></span></td><td><form method="post"><?=admin_form_return('admin_students.php')?><input type="hidden" name="action" value="student_status"><input type="hidden" name="student_id" value="<?=$s['id']?>"><select name="account_status"><option <?=$ast==='Active'?'selected':''?>>Active</option><option <?=$ast==='Inactive'?'selected':''?>>Inactive</option></select><button class="btn">Save</button></form></td></tr><?php endforeach; ?></table></div></section>
<script>(function(){const i=document.getElementById('student-search');if(i)i.addEventListener('input',function(){const q=this.value.toLowerCase().trim();document.querySelectorAll('#student-table tr[data-student-search]').forEach(r=>r.style.display=!q||r.dataset.studentSearch.includes(q)?'':'none');});})();</script>
